func statusLabel(li projection.LibraryItem) string {
	switch projection.LibraryStatus(li) {
	case "cutoff-unmet":
		return "Cutoff Unmet"
	case "downloaded":
		if li.Phase == "Transcoded" {
			return "Transcoded"
		}
		return "Downloaded"
	case "downloading":
		return "Downloading"
	default:
		return "Missing"
	}
}

// totalSize is the size of the item's files together.
func totalSize(files []FileRow) int64 {
	var total int64
	for _, f := range files {
		total += f.SizeBytes
	}
	return total
}

